/* gemm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "gemm.h"

/* ------------------------------------------------------------------------
 * Tunable blocking parameters.
 *
 * These control the tile sizes used in the blocked GEMM kernel below.
 * They are chosen conservatively to keep A/B/C tiles in L1/L2 cache on
 * typical x86-64 machines, but can be overridden at compile time if desired:
 *
 *   -DGEMM_BLOCK_I=64 -DGEMM_BLOCK_J=64 -DGEMM_BLOCK_K=64
 *
 * Changing these does not affect correctness, only performance.
 * ---------------------------------------------------------------------- */
#ifndef GEMM_BLOCK_I
#  define GEMM_BLOCK_I 32
#endif
#ifndef GEMM_BLOCK_J
#  define GEMM_BLOCK_J 32
#endif
#ifndef GEMM_BLOCK_K
#  define GEMM_BLOCK_K 32
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;

  /* Use row pointers to improve locality and reduce address computation
   * overhead; arithmetic is left unchanged to preserve exact semantics. */
  for (i = 0; i < ni; i++) {
    DATA_TYPE *Ci = C[i];
    for (j = 0; j < nj; j++)
      Ci[j] = (DATA_TYPE) ((i * j + 1) % ni) / ni;
  }

  for (i = 0; i < ni; i++) {
    DATA_TYPE *Ai = A[i];
    for (j = 0; j < nk; j++)
      Ai[j] = (DATA_TYPE) (i * (j + 1) % nk) / nk;
  }

  for (i = 0; i < nk; i++) {
    DATA_TYPE *Bi = B[i];
    for (j = 0; j < nj; j++)
      Bi[j] = (DATA_TYPE) (i * (j + 2) % nj) / nj;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  /* PolyBench provides possibly smaller, instrumented loop bounds via
   * _PB_NI/_PB_NJ/_PB_NK. Cache them in locals to avoid repeated macro
   * expansion and to keep the loops clean. */
  const int ni_bound = _PB_NI;
  const int nj_bound = _PB_NJ;
  const int nk_bound = _PB_NK;

  /* Local restricted aliases to help the compiler with alias analysis and
   * enable more aggressive vectorization. C, A, B themselves are not used
   * after this point, only the restricted versions are. */
  DATA_TYPE (* restrict C_)[nj] = C;
  DATA_TYPE (* restrict A_)[nk] = A;
  DATA_TYPE (* restrict B_)[nj] = B;

  /* Blocking factors (can be overridden via macros above). */
  const int TI = GEMM_BLOCK_I;
  const int TJ = GEMM_BLOCK_J;
  const int TK = GEMM_BLOCK_K;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* --------------------------------------------------------------------
   * 1. Scale C by beta: C = beta * C
   *
   * This is logically equivalent to the original inner-loop scaling
   * (which scaled each row i before updating it). Here we perform the
   * scaling for the whole matrix first. For every element C[i][j],
   * the order of operations remains:
   *
   *   C[i][j] := beta * C[i][j];
   *   C[i][j] := C[i][j] + sum_k(alpha * A[i][k] * B[k][j]);
   *
   * Only independent operations on different (i, j) pairs are
   * reordered, which does not change the result.
   * ------------------------------------------------------------------ */
  for (int i = 0; i < ni_bound; ++i) {
    DATA_TYPE * restrict Ci = C_[i];
    for (int j = 0; j < nj_bound; ++j) {
      Ci[j] *= beta;
    }
  }

  /* --------------------------------------------------------------------
   * 2. Blocked matrix multiplication:
   *      C += alpha * A * B
   *
   * The computation is reorganized into i/j/k tiles to improve data
   * locality:
   *
   *   - A[i][k] values from a block are reused across many j.
   *   - B[k][j] values from a block are reused across many i.
   *   - C[i][j] blocks stay in cache while being updated.
   *
   * For each fixed (i, j), contributions over k are accumulated in the
   * same order (k = 0..nk_bound-1) as in the original code: the k-loop
   * is only split into contiguous tiles (kk..k_end-1), preserving the
   * exact sequence of floating-point operations per element.
   *
   * The inner-most loop over j is manually unrolled by a factor of 4
   * to reduce loop overhead and expose more ILP/SIMD opportunities.
   * ------------------------------------------------------------------ */
  for (int ii = 0; ii < ni_bound; ii += TI) {
    const int i_end = (ii + TI < ni_bound) ? (ii + TI) : ni_bound;

    for (int kk = 0; kk < nk_bound; kk += TK) {
      const int k_end = (kk + TK < nk_bound) ? (kk + TK) : nk_bound;

      for (int jj = 0; jj < nj_bound; jj += TJ) {
        const int j_end  = (jj + TJ < nj_bound) ? (jj + TJ) : nj_bound;
        const int j_tile = j_end - jj;

        for (int i = ii; i < i_end; ++i) {
          /* Pointer to the beginning of the current C tile row. */
          DATA_TYPE * restrict Ci = &C_[i][jj];

          for (int k = kk; k < k_end; ++k) {
            /* Reuse A[i][k] * alpha across the entire row of the tile. */
            const DATA_TYPE a_ik_alpha = alpha * A_[i][k];
            const DATA_TYPE * restrict Bk = &B_[k][jj];

            int j = 0;
            const int unroll_limit = j_tile - 4; /* last j where j+3 < j_tile */

            /* Manually unrolled inner loop (factor 4). This preserves
             * the original computation order within the row segment. */
            for (; j <= unroll_limit; j += 4) {
              Ci[j + 0] += a_ik_alpha * Bk[j + 0];
              Ci[j + 1] += a_ik_alpha * Bk[j + 1];
              Ci[j + 2] += a_ik_alpha * Bk[j + 2];
              Ci[j + 3] += a_ik_alpha * Bk[j + 3];
            }

            /* Remainder loop for any leftover columns in this tile. */
            for (; j < j_tile; ++j) {
              Ci[j] += a_ik_alpha * Bk[j];
            }
          }
        }
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
