/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_gemm [[gnu::flatten, gnu::noinline]] (int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;
  int ii, jj, kk;
  int i_end, j_end, k_end;

  /* Create local restrict-qualified pointers to help the compiler
   * reason about aliasing and enable better vectorization.
   * We treat the incoming PolyBench storage as contiguous 2D arrays.
   */
  DATA_TYPE (*restrict C_)[nj] = (DATA_TYPE (*)[nj]) C;
  DATA_TYPE (*restrict A_)[nk] = (DATA_TYPE (*)[nk]) A;
  DATA_TYPE (*restrict B_)[nj] = (DATA_TYPE (*)[nj]) B;

  const int TI = GEMM_BLOCK_I;
  const int TJ = GEMM_BLOCK_J;
  const int TK = GEMM_BLOCK_K;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop

  /* 1. Scale C by beta once: C = beta * C.
   *
   * This pass is O(N^2) and negligible compared to the O(N^3) GEMM,
   * but keeping it separate makes the GEMM core simpler and easier
   * for the compiler to optimize and vectorize.
   */
  for (i = 0; i < _PB_NI; ++i) {
    DATA_TYPE *restrict c_row = &C_[i][0];
    for (j = 0; j < _PB_NJ; ++j) {
      c_row[j] *= beta;
    }
  }

  /* 2. Blocked matrix multiplication:
   *
   *   C += alpha * A * B
   *
   * We use a 3-level blocking over i, j, k to improve cache locality:
   *  - Inner-most loop over j accesses contiguous elements of C and B.
   *  - Blocks in k increase reuse of A and B in caches.
   *  - Blocks in i increase reuse of B rows across multiple C rows.
   *
   * The loops over k still visit k in monotonically increasing order
   * for each (i,j) pair, so the accumulation order for each element
   * C[i][j] is the same as in the original kernel.
   */
  for (ii = 0; ii < _PB_NI; ii += TI) {
    i_end = ii + TI;
    if (i_end > _PB_NI)
      i_end = _PB_NI;

    for (kk = 0; kk < _PB_NK; kk += TK) {
      k_end = kk + TK;
      if (k_end > _PB_NK)
        k_end = _PB_NK;

      for (jj = 0; jj < _PB_NJ; jj += TJ) {
        j_end = jj + TJ;
        if (j_end > _PB_NJ)
          j_end = _PB_NJ;

        const int j_len = j_end - jj;

        for (i = ii; i < i_end; ++i) {
          DATA_TYPE *restrict       c_row = &C_[i][jj];
          const DATA_TYPE *restrict a_row = &A_[i][0];

          for (k = kk; k < k_end; ++k) {
            /* Precompute alpha * A[i][k] once per (i,k) and reuse across
             * the entire j-block. This reduces the number of floating-point
             * multiplications on the critical path.
             */
            const DATA_TYPE a_ik_alpha = alpha * a_row[k];
            const DATA_TYPE *restrict b_row = &B_[k][jj];

            /* Inner-most loop: contiguous access over j in both C and B.
             * The restrict-qualified pointers and unit stride enable the
             * compiler to aggressively vectorize this loop.
             */
            for (j = 0; j < j_len; ++j) {
              c_row[j] += a_ik_alpha * b_row[j];
            }
          }
        }
      }
    }
  }

#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nj,  POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
