/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nj,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations applied (while preserving original semantics):
   - Use local restrict-qualified pointers for A, B and C to help the
     compiler's alias analysis.
   - Hoist loop-invariant expressions: alpha * A[i][k] is computed once
     per (i, k) and reused across the inner j loop.
   - Replace repeated 2D indexing with row pointers and linear indexing,
     improving cache locality and making the access pattern clearer.
   - Manually unroll the inner j-loop by a small factor (4) to increase
     instruction-level parallelism and encourage vectorization.
*/
static
void kernel_gemm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,NI,NJ,ni,nj),
		 DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		 DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj))
{
  int i, j, k;

  /* Create local restrict-qualified views of the matrices.
     PolyBench guarantees that A, B, and C do not alias; expressing this
     here allows the compiler to generate more aggressive optimizations. */
  DATA_TYPE (* restrict C_)[nj] = C;
  DATA_TYPE (* restrict A_)[nk] = A;
  DATA_TYPE (* restrict B_)[nj] = B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  /* Keep the original PolyBench SCoP region so that external polyhedral
     tools still recognize the kernel. */
#pragma scop
  for (i = 0; i < _PB_NI; i++) {
    /* Cache the current row of C; this improves locality and simplifies
       the inner loops into 1D operations on Ci. */
    DATA_TYPE * restrict Ci = C_[i];
    const int nj_bound = _PB_NJ;

    /* Scale row i of C by beta.
       This loop is written in terms of a single pointer with a small
       manual unroll to help vectorization. */
    j = 0;
    for (; j + 3 < nj_bound; j += 4) {
      Ci[j]     *= beta_;
      Ci[j + 1] *= beta_;
      Ci[j + 2] *= beta_;
      Ci[j + 3] *= beta_;
    }
    for (; j < nj_bound; ++j) {
      Ci[j] *= beta_;
    }

    /* GEMM update:
       Original semantics:
         for (k)
           for (j)
             C[i][j] += alpha * A[i][k] * B[k][j];

       We keep the i-k-j loop ordering (good spatial locality on B, since
       j is the innermost index for row-major storage), but:
       - compute aik = alpha * A[i][k] once per (i, k),
       - operate on Ci[] and Bk[] via pointers,
       - unroll the j loop by 4. */
    for (k = 0; k < _PB_NK; k++) {
      const DATA_TYPE aik = alpha_ * A_[i][k];
      const DATA_TYPE * restrict Bk = B_[k];

      j = 0;
      /* Unrolled inner loop: update 4 consecutive elements of C in one
         iteration, using contiguous accesses to both Ci and Bk. */
      for (; j + 3 < nj_bound; j += 4) {
        Ci[j]     += aik * Bk[j];
        Ci[j + 1] += aik * Bk[j + 1];
        Ci[j + 2] += aik * Bk[j + 2];
        Ci[j + 3] += aik * Bk[j + 3];
      }
      /* Handle remaining columns (if nj is not a multiple of 4). */
      for (; j < nj_bound; ++j) {
        Ci[j] += aik * Bk[j];
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);

  /* Initialize array(s). */
  init_array (ni, nj, nk, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_gemm (ni, nj, nk,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
