   * in allocation, while `_PB_*` (below) are the possibly smaller problem
   * sizes actually iterated over for measurement.
   */
  const int ni_full = ni;
  const int nj_full = nj;
  const int nk_full = nk;

  DATA_TYPE (*restrict C_)[nj_full]       = C;
  const DATA_TYPE (*restrict A_)[nk_full] = A;
  const DATA_TYPE (*restrict B_)[nj_full] = B;

  /* Use the PolyBench “problem size” macros for loop bounds, as in the
   * original code, to stay consistent with the benchmarking harness. */
  const int ni_iter = _PB_NI;
  const int nj_iter = _PB_NJ;
  const int nk_iter = _PB_NK;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

//BLAS PARAMS
//TRANSA = 'N'
//TRANSB = 'N'
// => Form C := alpha*A*B + beta*C,
//A is NIxNK
//B is NKxNJ
//C is NIxNJ
#pragma scop
  /* Outer loop over rows of C and A. */
  for (i = 0; i < ni_iter; i++) {
    /* Row pointers for current i (improves locality and reduces indexing). */
    DATA_TYPE *restrict       Ci = C_[i];
    const DATA_TYPE *restrict Ai = A_[i];

    /* Block over columns (J dimension) for better cache usage of C and B. */
    for (int j_block = 0; j_block < nj_iter; j_block += GEMM_J_BLOCK) {
      const int j_end       = (j_block + GEMM_J_BLOCK < nj_iter)
                              ? (j_block + GEMM_J_BLOCK) : nj_iter;
      const int block_width = j_end - j_block;

      /* Pointers to the start of the current C block. */
      DATA_TYPE *restrict Ci_block = Ci + j_block;

      /* 1) Scale C block by beta (exactly once per element, as in original). */
      for (int jj = 0; jj < block_width; ++jj) {
        Ci_block[jj] *= beta_;
      }

      /* 2) Accumulate alpha * A * B into this C block, tiled in K. */
      for (int k_block = 0; k_block < nk_iter; k_block += GEMM_K_BLOCK) {
        const int k_end = (k_block + GEMM_K_BLOCK < nk_iter)
                          ? (k_block + GEMM_K_BLOCK) : nk_iter;

        /* For each k in this K-block, add a rank-1 update:
         *   C[i, j_block:(j_end-1)] += (alpha * A[i,k]) * B[k, j_block:(j_end-1)]
         */
        for (k = k_block; k < k_end; ++k) {
          const DATA_TYPE aik = alpha_ * Ai[k];

          /* Row pointer for B at the current k, restricted to the J-block. */
          const DATA_TYPE *restrict Bk_block = &B_[k][j_block];

          /* Inner-most loop: contiguous in memory for both Ci_block and
           * Bk_block, ideal for vectorization.
